import { DatabaseSync } from 'node:sqlite';

/**
 * Devices table.
 *
 - serial       : path identifier (primary key)
 - name         : display name
 - tags         : JSON array of strings
 - config       : JSON object (desired-state config)
 - state        : canonical serialization of {name, tags, config}; used to
                  detect byte-identical repeats of a PUT
 - created_at   : ISO-8601 UTC, set once on insert
 - updated_at   : ISO-8601 UTC, bumped ONLY when state actually changes
 */
const SCHEMA = `
  CREATE TABLE IF NOT EXISTS devices (
    serial     TEXT PRIMARY KEY,
    name       TEXT NOT NULL,
    tags       TEXT NOT NULL,
    config     TEXT NOT NULL,
    state      TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
  );
`;

export function createDb(path = ':memory:') {
  const db = new DatabaseSync(path);
  db.exec(SCHEMA);

  const stmts = {
    get: db.prepare('SELECT * FROM devices WHERE serial = ?'),
    insert: db.prepare(`
      INSERT INTO devices (serial, name, tags, config, state, created_at, updated_at)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `),
    update: db.prepare(`
      UPDATE devices
      SET name = ?, tags = ?, config = ?, state = ?, updated_at = ?
      WHERE serial = ?
    `),
  };

  return {
    /** Raw row (JSON columns still strings) or undefined. */
    getRaw(serial) {
      return stmts.get.get(serial);
    },
    /** Row with tags/config parsed back to JS values. */
    get(serial) {
      const row = stmts.get.get(serial);
      if (!row) return undefined;
      return hydrate(row);
    },
    insert({ serial, name, tags, config, state, createdAt, updatedAt }) {
      stmts.insert.run(serial, name, JSON.stringify(tags), JSON.stringify(config), state, createdAt, updatedAt);
    },
    update({ serial, name, tags, config, state, updatedAt }) {
      stmts.update.run(name, JSON.stringify(tags), JSON.stringify(config), state, updatedAt, serial);
    },
    close() {
      db.close();
    },
  };
}

function hydrate(row) {
  return {
    serial: row.serial,
    name: row.name,
    tags: JSON.parse(row.tags),
    config: JSON.parse(row.config),
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

