import express from 'express';
import { stableStringify, deepMerge } from './canonical.js';

/**
 * PUT /devices/:serial — idempotent upsert of a device's full desired state.
 *
 * Request body: { name: string, tags: string[], config: object }
 *
 * Semantics:
 *  - serial not present            -> create (201)
 *  - serial present, state changes -> update (200), updated_at bumped
 *  - serial present, resulting state identical to stored state
 *                                  -> 200 + `X-Idempotent: unchanged`,
 *                                     updated_at untouched
 *  - config is merged recursively into the stored config (merge semantics);
 *    name and tags replace wholesale.
 *  - If-Unmodified-Since: if the stored updated_at is NEWER than the header
 *    value (second granularity, per RFC 7232), the write is rejected with 412.
 *
 * Responses carry the hydrated device resource:
 *   { serial, name, tags, config, createdAt, updatedAt }
 */
export function createApp(db) {
  const app = express();
  app.use(express.json());

  app.put('/devices/:serial', (req, res) => {
    const { serial } = req.params;

    // ---- validate desired state -------------------------------------------
    const { name, tags, config } = req.body ?? {};
    if (typeof name !== 'string' || name.length === 0) {
      return res.status(400).json({ error: "'name' must be a non-empty string" });
    }
    if (!Array.isArray(tags) || tags.some((t) => typeof t !== 'string')) {
      return res.status(400).json({ error: "'tags' must be an array of strings" });
    }
    if (config !== undefined && !isPlainObject(config)) {
      return res.status(400).json({ error: "'config' must be an object" });
    }

    const existing = db.get(serial);
    const incomingConfig = config ?? {};

    // ---- conditional request: If-Unmodified-Since --------------------------
    if (existing) {
      const stale = checkUnmodifiedSince(req.get('If-Unmodified-Since'), existing.updatedAt);
      if (stale) {
        return res.status(412).json({
          error: 'precondition failed',
          detail: `resource was modified at ${existing.updatedAt}, after ${stale.header}`,
        });
      }
    }

    // ---- create ------------------------------------------------------------
    if (!existing) {
      const now = new Date().toISOString();
      const desired = { name, tags, config: structuredClone(incomingConfig) };
      db.insert({
        serial,
        ...desired,
        state: stableStringify(desired),
        createdAt: now,
        updatedAt: now,
      });
      return res.status(201).json(db.get(serial));
    }

    // ---- merge semantics ----------------------------------------------------
    const merged = {
      name,
      tags,
      config: deepMerge(existing.config, incomingConfig),
    };

    // ---- no-op detection: byte-identical repeat ------------------------------
    if (stableStringify(merged) === stableStringify({ name: existing.name, tags: existing.tags, config: existing.config })) {
      return res
        .status(200)
        .set('X-Idempotent', 'unchanged')
        .json(db.get(serial)); // updated_at deliberately not touched
    }

    // ---- real update ---------------------------------------------------------
    db.update({
      serial,
      ...merged,
      state: stableStringify(merged),
      updatedAt: new Date().toISOString(),
    });
    return res.status(200).json(db.get(serial));
  });

  // Convenience for inspection/debugging.
  app.get('/devices/:serial', (req, res) => {
    const device = db.get(req.params.serial);
    if (!device) return res.status(404).json({ error: 'not found' });
    res.json(device);
  });

  return app;
}

/**
 * RFC 7232 If-Unmodified-Since: succeed unless the entity was modified after
 * the given date. HTTP dates have second resolution, so compare at second
 * granularity. Returns the parsed header value when the precondition FAILS
 * (i.e. resource is newer => stale => 412), otherwise null/undefined.
 */
function checkUnmodifiedSince(headerValue, updatedAtIso) {
  if (!headerValue) return null;
  const sinceMs = Date.parse(headerValue);
  if (Number.isNaN(sinceMs)) return null; // malformed header -> ignore per RFC
  const updatedSec = Math.floor(Date.parse(updatedAtIso) / 1000);
  const sinceSec = Math.floor(sinceMs / 1000);
  return updatedSec > sinceSec ? { header: headerValue } : null;
}

function isPlainObject(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

