import { test, describe, beforeEach } from 'node:test';
import assert from 'node:assert/strict';
import request from 'supertest';

import { createApp } from '../src/app.js';
import { createDb } from '../src/db.js';

const SERIAL = 'dev-001';
const BODY = {
  name: 'thermostat-lobby',
  tags: ['hvac', 'lobby'],
  config: { setpointC: 21, mode: 'auto', schedule: { mon: '06:00' } },
};

describe('PUT /devices/:serial — idempotent upsert', () => {
  let app;
  let db;

  beforeEach(() => {
    db = createDb(':memory:');
    app = createApp(db);
  });

  const rowOf = (serial) => db.getRaw(serial);

  test('create -> 201 with created resource and timestamps set', async () => {
    const res = await request(app).put(`/devices/${SERIAL}`).send(BODY);

    assert.equal(res.status, 201);
    assert.equal(res.body.serial, SERIAL);
    assert.deepEqual(res.body.tags, BODY.tags);
    assert.deepEqual(res.body.config, BODY.config);
    assert.equal(res.body.createdAt, res.body.updatedAt);

    // persisted
    const row = rowOf(SERIAL);
    assert.ok(row, 'row exists in DB');
    assert.equal(row.name, BODY.name);
  });

  test('update changed state -> 200 and bumps updated_at only', async () => {
    await request(app).put(`/devices/${SERIAL}`).send(BODY);
    const before = rowOf(SERIAL);

    await new Promise((r) => setTimeout(r, 20)); // ensure clock advances

    const res = await request(app)
      .put(`/devices/${SERIAL}`)
      .send({ ...BODY, name: 'thermostat-renamed' });

    assert.equal(res.status, 200);
    assert.notEqual(res.get('X-Idempotent'), 'unchanged');
    assert.equal(res.body.name, 'thermostat-renamed');

    const after = rowOf(SERIAL);
    assert.equal(after.created_at, before.created_at); // create timestamp frozen
    assert.ok(after.updated_at > before.updated_at, 'updated_at advanced');
  });

  test('merge semantics: config deep-merges, sibling keys survive', async () => {
    await request(app).put(`/devices/${SERIAL}`).send(BODY);

    const res = await request(app)
      .put(`/devices/${SERIAL}`)
      .send({ name: BODY.name, tags: ['hvac'], config: { setpointC: 23, schedule: { tue: '07:00' } } });

    assert.equal(res.status, 200);
    assert.deepEqual(res.body.config, {
      setpointC: 23,        // overridden
      mode: 'auto',         // preserved
      schedule: { mon: '06:00', tue: '07:00' }, // merged recursively
    });
    assert.deepEqual(res.body.tags, ['hvac']); // arrays replace wholesale
  });

  test('byte-identical repeat PUT -> 200 + X-Idempotent: unchanged, updated_at untouched', async () => {
    await request(app).put(`/devices/${SERIAL}`).send(BODY);

    // Freeze the DB timestamp: capture it before the repeat.
    const before = rowOf(SERIAL);
    assert.ok(before.updated_at, 'timestamp readable from DB');

    // Repeat the exact same PUT (different key order in config to prove
    // canonical comparison, still byte-equivalent desired state).
    const res = await request(app)
      .put(`/devices/${SERIAL}`)
      .send({
        tags: [...BODY.tags],
        name: BODY.name,
        config: { mode: 'auto', schedule: { mon: '06:00' }, setpointC: 21 },
      });

